SysDataModelXML.JavaScript:
scan_if = function () {
    return 2;
}
scan_para = function (id, r) {
    $("#linkinput").blur();
    scan_impl(id, "#" + r + "#");
}

scanAfterAction = function (id) {
    var webId = plus.webview.currentWebview().id
    if (webId.indexOf("modelpara") != -1) {
        if ($("#提示").val() != "OK") {
            alert($("#提示").val())
            return;
        } else {
            var dmPara = reParaList();
            showModelData(dmPara)
        }
    }
};

$("#linkreset").remove() //,#linkok



var functype = plus.webview.currentWebview().functype;
reScanFlag = function (id) {
    if (functype && id == "linkinput" && functype.indexOf("new") != -1) { return true }
    return false
}
beforeFunction = function (sta, id) {
    if (functype && functype.indexOf("new") != -1 && (sta == "autoSave" || id == "linkok")) {
        if ($("#DATACK").val() != "OK") {
            //playAudio("_www/libs/audio/error.wav")
            $("#linkinput").focus();
            alert($("#DATACK").val())
            return true;
        }
    }
    return false;
}


afterFunction = function (sta,id) {
    //删除后自动刷新
    if (sta == "linkquick12")
        reloadModelData()
    if (id == "linkok" || sta == "autoSave") {
        //playAudio("_www/libs/audio/success.wav")
        $("#linkinput").focus();
    }
}

Save_Data = function (data, ele) {//返回之后刷新
    var con = plus.webview.getWebviewById('contentlist');
    mui.fire(con, 'contentlist_local', {})

}

repeatTime = function (id) {
    if (id == "linkpreprocess")//21模型按钮触发时间
        return 10
}


if (functype && functype == "edit") {
    $(document).on("input", "#QTY", function () {

        var qty = parseFloat($("#QTY").val()) || 0;         // 输入包装数量
        var stkQty = parseFloat($("#STKQTY").val()) || 0;   // 库位包装数
        var uomcoe = parseFloat($("#UOMCOE").val()) || 0;   // 单包数量
        var nedQty = parseFloat($("#NEDQTY").val()) || 0;   // 需领包数
        var nedQtyStu = parseFloat($("#NEDQTYSTU").val()) || 0; // 需领数量

        if (stkQty <= 0 || uomcoe <= 0) {
            $("#QTY").val("");
            $("#QTYSTU").val("");
            alert("请先选择库存");
            return;
        }

        if (qty > stkQty) {
            $("#QTY").val("");
            $("#QTYSTU").val("");
            alert("包装数量不能大于库位包装数");
            return;
        }

        if (qty > nedQty) {
            $("#QTY").val("");
            $("#QTYSTU").val("");
            alert("包装数量不能大于剩余需领包数");
            return;
        }

        var qtyStu = qty * uomcoe;
        $("#QTYSTU").val(qtyStu.toFixed(2));
    });
}


editWebs = function () {

    var nedQty = parseFloat($("#NEDQTY").val()) || 0;
    var nedQtyStu = parseFloat($("#NEDQTYSTU").val()) || 0;
    var Qty = parseFloat($("#QTY").val()) || 0;
    var QtyStu = parseFloat($("#QTYSTU").val()) || 0;

    var newnedQty = (nedQty - Qty).toFixed(2);

    if (newnedQty <= 0) {
        showModelData(null);
        return;
    }

    $("#NEDQTY").val(newnedQty)
    $("#NEDQTYSTU").val((nedQtyStu - QtyStu).toFixed(2))

    $("#QTY").val("");
    $("#QTYSTU").val("");

    var con = plus.webview.getWebviewById('contentlist');
    mui.fire(con, 'contentlist_local', {});
}
